class OrderedStream {
  constructor(n) {
    this.values = new Array(n + 1).fill(null);
    this.pointer = 1;
  }

  insert(idKey, value) {
    this.values[idKey] = value;
    const chunk = [];
    while (this.pointer < this.values.length && this.values[this.pointer] !== null) {
      chunk.push(this.values[this.pointer]);
      this.pointer++;
    }
    return chunk;
  }
}

