class OrderedStream {
  constructor(n) {
    this.n = n;
    this.stored = new Map();
    this.emitted = 0;
  }

  insert(idKey, value) {
    this.stored.set(idKey, value);
    const ready = [];
    for (let id = 1; id <= this.n && this.stored.has(id); id++) ready.push(this.stored.get(id));
    const chunk = ready.slice(this.emitted);
    this.emitted = ready.length;
    return chunk;
  }
}

