function generate(rand, size) {
  const n = size === 'large' ? 499 : 1 + Math.floor(rand() * 8);
  const letters = size === 'large' || rand() < 0.5 ? 'abcdefghijklmnopqrstuvwxyz' : 'ab';
  const ids = Array.from({ length: n }, (_, i) => i + 1);
  const shape = rand();
  if (shape < 0.15) ids.reverse();
  else if (shape > 0.3) {
    for (let i = n - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [ids[i], ids[j]] = [ids[j], ids[i]];
    }
  }
  const word = () => Array.from({ length: 5 }, () => letters[Math.floor(rand() * letters.length)]).join('');
  return [['OrderedStream', ...ids.map(() => 'insert')], [[n], ...ids.map(id => [id, word()])]];
}

