function validate([operations, args]) {
  const n = args[0][0];
  if (n < 1 || n > 1000) return 'n is between 1 and 1000.';
  if (operations.length - 1 !== n) return 'insert must be called exactly n times.';
  const seen = new Set();
  for (let i = 1; i < operations.length; i++) {
    const [idKey, value] = args[i];
    if (idKey < 1 || idKey > n) return 'Each idKey is between 1 and n.';
    if (seen.has(idKey)) return 'Each idKey may be inserted only once.';
    seen.add(idKey);
    if (!/^[a-z]{5}$/.test(value)) return 'Each value is exactly 5 lowercase letters.';
  }
  return null;
}
